@Service
@RequiredArgsConstructor
public class OrderService {
    private final OrderMapper orderMapper;
    private final OrderService self;        // 注入自身代理（或拆到另一个 Bean）

    public void placeOrder(Order o) {
        // this.save(o);  // ❌ 自调用，不走代理，事务失效
        self.save(o);     // ✅ 走代理
    }

    @Transactional(rollbackFor = Exception.class)
    public void save(Order o) throws Exception {
        orderMapper.insert(o);
        if (o.getAmount() == null) {
            throw new Exception("金额为空");  // 受检异常，配了 rollbackFor 才回滚
        }
    }
}
// 注：注入自身需 @Lazy 或允许循环引用；更推荐把事务方法拆到独立 Bean。
